package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen0Test {

    @Test
    public void testNormalizedStandard_BasicDuration() {
        // Test case where only duration fields (days, hours, etc.) are present
        // This tests the millis calculation logic
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8, PeriodType.dayAndTime());
        Period result = period.normalizedStandard(PeriodType.dayAndTime());

        assertEquals(4, result.getDays());
        assertEquals(5, result.getHours());
        assertEquals(6, result.getMinutes());
        assertEquals(7, result.getSeconds());
        assertEquals(8, result.getMillis());
        assertEquals(PeriodType.dayAndTime(), result.getPeriodType());
    }

    @Test
    public void testNormalizedStandard_WithYearsAndMonths() {
        // Test case where years and months are present. 
        // Tests the branch: if (years != 0 || months != 0)
        // and the logic: years = FieldUtils.safeAdd(years, months / 12); months = months % 12;
        Period period = new Period(1, 13, 0, 0, 0, 0, 0, 0, PeriodType.yearAndTime());
        Period result = period.normalizedStandard(PeriodType.yearAndTime());

        // 1 year + 13 months = 2 years, 1 month
        assertEquals(2, result.getYears());
        assertEquals(1, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_WithOnlyMonthsOverflow() {
        // Test case where years is 0 but months > 12
        Period period = new Period(0, 25, 0, 0, 0, 0, 0, 0, PeriodType.yearAndTime());
        Period result = period.normalizedStandard(PeriodType.yearAndTime());

        assertEquals(2, result.getYears());
        assertEquals(1, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_WithOnlyYears() {
        // Test case where years != 0 but months == 0
        // Tests the branch: if (months != 0)
        Period period = new Period(2, 0, 0, 0, 0, 0, 0, 0, PeriodType.yearAndTime());
        Period result = period.normalizedStandard(PeriodType.yearAndTime());

        assertEquals(2, result.getYears());
        assertEquals(0, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_NoYearMonthFields() {
        // Test case where years == 0 and months == 0
        // Tests the branch: if (years != 0 || months != 0) is false
        Period period = new Period(0, 0, 1, 1, 1, 1, 1, 1, PeriodType.dayAndTime());
        Period result = period.normalizedStandard(PeriodType.dayAndTime());

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(1, result.getDays());
    }

    @Test
    public void testNormalizedStandard_NegativeFields() {
        // Test case with negative values to ensure math remains consistent
        // Note: Java % operator on negative numbers: -13 % 12 = -1
        Period period = new Period(-1, -13, 0, 0, 0, 0, 0, 0, PeriodType.yearAndTime());
        Period result = period.normalizedStandard(PeriodType.yearAndTime());

        // -1 year + (-13/12) = -1 + (-1) = -2
        // -13 % 12 = -1
        assertEquals(-2, result.getYears());
        assertEquals(-1, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_LargeMillis() {
        // Test case for potential overflow in millis calculation (though code says no overflow happens)
        // Using max values for duration fields
        Period period = new Period(0, 0, 0, 30, 23, 59, 59, 999, PeriodType.dayAndTime());
        Period result = period.normalizedStandard(PeriodType.dayAndTime());

        assertEquals(30, result.getDays());
        assertEquals(23, result.getHours());
        assertEquals(59, result.getMinutes());
        assertEquals(59, result.getSeconds());
        assertEquals(999, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_WeeksNormalization() {
        // Test that weeks are converted into days via the millis calculation
        // 1 week = 7 days
        Period period = new Period(0, 0, 1, 0, 0, 0, 0, 0, PeriodType.weekAndTime());
        Period result = period.normalizedStandard(PeriodType.weekAndTime());

        // Depending on PeriodType, weeks might be converted to days in the millis sum
        // If type is weekAndTime, it should preserve weeks if the implementation allows,
        // but the millis calculation treats weeks as 7 days.
        // Joda Period standard normalization for weekAndTime usually results in days.
        assertTrue(result.getDays() >= 7 || result.getWeeks() == 1);
    }
}
